"""Consume literal identities generated by the unchanged Python public owner."""
from __future__ import annotations

import copy
import json
import struct
from pathlib import Path
from typing import Any

import pytest

from nirs4all_io.dataset_facade import to_u07_raw_sources
from nirs4all_io.public_content import canonical_source_schema, compatible_source_schemas
from nirs4all_io.public_dataset import dataset

FIXTURES = Path(__file__).parent / "fixtures"
BANK = json.loads((FIXTURES / "source_schema_canonical_vectors.json").read_text(encoding="utf-8"))
CASES = {case["id"]: case for case in BANK["cases"]}
GROUPS = list(dict.fromkeys(case_id.split(".")[0] for case_id in CASES))


def assert_typed(actual: Any, expected: Any) -> None:
    assert type(actual) is type(expected), (actual, expected)
    if type(expected) is float:
        assert struct.pack(">d", actual) == struct.pack(">d", expected)
    elif isinstance(expected, dict):
        assert actual.keys() == expected.keys()
        for key, value in expected.items():
            assert_typed(actual[key], value)
    elif isinstance(expected, list):
        assert len(actual) == len(expected)
        for a, b in zip(actual, expected, strict=True):
            assert_typed(a, b)
    else:
        assert actual == expected


@pytest.mark.parametrize("case", BANK["cases"], ids=list(CASES))
def test_shared_literal_source_schema(case: dict[str, Any]) -> None:
    actual = canonical_source_schema(case["input"])
    expected = case["expected"]
    assert actual["identity"].encode("utf-8") == expected["identity"].encode("utf-8")
    assert_typed(actual, expected)
    # Canonical descriptors have absent null units and must remain byte-stable.
    assert_typed(canonical_source_schema(expected), expected)
    assert list(actual) == list(case["input"])
    assert_typed(json.loads(actual["identity"]), json.loads(expected["identity"]))


def test_literal_anchors_and_fixture_copies() -> None:
    assert BANK["schema"] == "nirs4all.io.source-schema-canonical-vectors.v1"
    assert len(CASES) == len(BANK["cases"]) == 40
    crate_copy = FIXTURES.parents[1] / "crates/nirs4all-io-core/tests/fixtures/source_schema_canonical_vectors.json"
    assert crate_copy.read_bytes() == (FIXTURES / "source_schema_canonical_vectors.json").read_bytes()
    for case_id, literal in (
        ("integer.nir", '"wavelength":[900,910,920]'),
        ("integral_float.nir", '"wavelength":[900.0,910.0,920.0]'),
        ("mixed.nir", '"wavelength":[900,910.0,920]'),
        ("adjacent.nir", '"wavelength":[1e-07,1.0000000000000001e-07,2e-07]'),
        ("geometry.nir", '"wavelength":[-0.0,1.5e-300,1e-07]'),
    ):
        assert literal in CASES[case_id]["expected"]["identity"]
    assert 'quote\\" backslash\\\\ newline\\n control\\u0001 separator\u2028' in CASES["geometry.metadata"]["expected"]["identity"]


def test_compatibility_keeps_saved_literal() -> None:
    current = {"nir": CASES["base.nir"]["input"]}
    saved = {"nir": CASES["permuted.nir"]["input"]}
    assert_typed(compatible_source_schemas(current, saved), saved)
    with pytest.raises(ValueError, match="schema differs"):
        compatible_source_schemas(current, {"nir": CASES["integer.nir"]["input"]})
    saved = {"nir": CASES["geometry.nir"]["input"]}
    current = copy.deepcopy(saved)
    descriptor = json.loads(current["nir"]["identity"])
    descriptor["axis_coordinates"]["wavelength"][0] = 0
    current["nir"]["identity"] = json.dumps(descriptor)
    assert_typed(compatible_source_schemas(current, saved), saved)


def flatten(value: Any) -> list[Any]:
    if isinstance(value, list):
        return [cell for child in value for cell in flatten(child)]
    return [value]


@pytest.mark.parametrize("group", GROUPS)
def test_original_public_wrapper_composes_through_python_owner(group: str) -> None:
    original = json.loads((FIXTURES / "runtime-u07-groups.json").read_text(encoding="utf-8"))
    schemas = {}
    for source in original["dataset"]["sources"]:
        case = CASES[f'{group}.{source["name"]}']
        descriptor = json.loads(case["input"]["identity"])
        for field in ("axis_units", "axis_coordinates", "feature_names"):
            source[field] = descriptor[field]
        source["array"]["dtype"] = case["input"]["dtype"]
        if group == "tabular_text" and source["name"] == "metadata":
            source["array"]["values"] = [["20.5", "A"], ["21.5", "B"]]
        schemas[source["name"]] = case["expected"]
    sources = {}
    for source in original["dataset"]["sources"]:
        entry = {"sample_ids": original["dataset"]["sample_ids"], "descriptor": schemas[source["name"]], "shape": source["array"]["shape"]}
        entry["rows" if source["name"] == "metadata" else "data"] = source["array"]["values"] if source["name"] == "metadata" else flatten(source["array"]["values"])
        sources[source["name"]] = entry
    expected = {"sample_ids": original["dataset"]["sample_ids"], "source_schemas": schemas, "sources": sources}
    # Python requires explicit Dataset construction and then its multimodal input.
    actual = to_u07_raw_sources(dataset(original).multimodal)
    assert_typed(actual, expected)


@pytest.mark.parametrize("actual,expected", [(True, 1), (1, 1.0), (-0.0, 0.0)])
def test_typed_comparator_rejects_kind_and_bit_drift(actual: Any, expected: Any) -> None:
    with pytest.raises(AssertionError):
        assert_typed(actual, expected)
